import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (character) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[character]));

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)} · Workboard</title>
<style>
  * { box-sizing: border-box; }
  body { margin: 0; background: #f5f7fa; color: #182536; font-family: system-ui, sans-serif; }
  main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dce2e9; border-radius: 12px; }
  h1 { margin-top: 0; overflow-wrap: anywhere; }
  label { display: block; font-weight: 600; margin-bottom: 8px; }
  .fields { display: flex; gap: 12px; flex-wrap: wrap; }
  input[type="text"] { flex: 1; min-width: 180px; padding: 12px; border: 1px solid #8290a0; border-radius: 6px; font: inherit; }
  input[type="checkbox"] { width: 20px; height: 20px; cursor: pointer; }
  select { padding: 10px; font: inherit; }
  .filter { margin-top: 24px; }
  button:disabled, input:disabled { cursor: default; opacity: 0.6; }
  .actions { display: flex; gap: 8px; flex-wrap: wrap; }
  button { padding: 12px 18px; border: 1px solid #2056ad; border-radius: 6px; background: #2056ad; color: white; font: inherit; cursor: pointer; }
  :focus-visible { outline: 3px solid #d38b13; outline-offset: 3px; }
  ul { padding: 0; list-style: none; }
  li { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 16px; border-top: 1px solid #dce2e9; padding: 18px 0; }
  .name { overflow-wrap: anywhere; min-width: 0; }
  li form { flex-shrink: 0; }
  [role="alert"] { color: #9d241e; }
  .empty { color: #566578; }
  @media (max-width: 600px) { main { margin: 20px 12px; padding: 20px; } }
</style>
</head>
<body><main>${content}</main></body>
</html>`;
}

function sendHtml(response, status, html) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(html);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 65536) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

export function createApp(databasePath) {
  mkdirSync(dirname(databasePath), { recursive: true });
  const database = new DatabaseSync(databasePath);
  database.exec('PRAGMA foreign_keys = ON');
  database.exec(`CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK(length(trim(name)) > 0)
  )`);
  database.exec(`CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL CHECK(length(trim(title)) > 0),
    completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id)`);
  // Existing project databases predate archive state; migrate without replacing rows.
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0, 1))');
  }
  const listProjects = database.prepare(`SELECT projects.id, projects.name,
    COUNT(tasks.id) AS total, COALESCE(SUM(tasks.completed), 0) AS completed
    FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
    WHERE projects.archived = ? GROUP BY projects.id ORDER BY projects.id ASC`);
  const findProject = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
  const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
  const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const listTasks = database.prepare(`SELECT id, title, completed FROM tasks
    WHERE project_id = ? AND (? = 'All' OR completed = ?) ORDER BY id ASC`);
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
  const findTask = database.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?');
  const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');

  function taskRow(task, project, filter, renameError) {
    const disabled = project.archived ? ' disabled' : '';
    return `<li data-testid="task-row"><span class="name">${escapeHtml(task.title)}</span>
<form method="post" action="/projects/${project.id}/tasks/${task.id}/completion"><input type="hidden" name="filter" value="${filter}"><input type="checkbox" name="completed" value="1" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''}${disabled} onchange="this.form.requestSubmit()"><noscript><button type="submit"${disabled}>Save completion</button></noscript></form>
<form method="post" action="/projects/${project.id}/tasks/${task.id}/rename">
<input type="hidden" name="filter" value="${filter}">
<label for="new-task-title-${task.id}">New task title</label>
<div class="fields"><input id="new-task-title-${task.id}" name="title" type="text" value="${escapeHtml(task.title)}"${disabled}${renameError ? ` aria-describedby="task-rename-error-${task.id}" aria-invalid="true"` : ''}><button type="submit"${disabled}>Rename task</button></div>
${renameError ? `<p id="task-rename-error-${task.id}" role="alert">${escapeHtml(renameError)}</p>` : ''}
</form></li>`;
  }

  function projectPage(project, filter, { taskError = '', renameError = '', taskRenameError = '', taskRenameId } = {}) {
    const tasks = listTasks.all(project.id, filter, filter === 'Completed' ? 1 : 0);
    return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
<form action="/" method="get"><button type="submit">Projects</button></form>
${project.archived ? '<p>Archived project</p>' : ''}
<form method="post" action="/projects/${project.id}/rename">
<input type="hidden" name="filter" value="${filter}">
<label for="new-project-name">New project name</label>
<div class="fields"><input id="new-project-name" name="name" type="text" value="${escapeHtml(project.name)}"${project.archived ? ' disabled' : ''}${renameError ? ' aria-describedby="rename-error" aria-invalid="true"' : ''}><button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button></div>
${renameError ? `<p id="rename-error" role="alert">${escapeHtml(renameError)}</p>` : ''}
</form>
<h2>Tasks</h2>
<form method="post" action="/projects/${project.id}/tasks">
<input type="hidden" name="filter" value="${filter}">
<label for="task-title">Task title</label>
<div class="fields"><input id="task-title" name="title" type="text"${taskError ? ' aria-describedby="task-error" aria-invalid="true"' : ''}><button type="submit"${project.archived ? ' disabled' : ''}>Create task</button></div>
${taskError ? `<p id="task-error" role="alert">${escapeHtml(taskError)}</p>` : ''}
</form>
<form class="filter" method="get" action="/projects/${project.id}">
<label for="task-filter">Task filter</label>
<select id="task-filter" name="filter" onchange="this.form.requestSubmit()">${['All', 'Open', 'Completed'].map((option) => `<option${option === filter ? ' selected' : ''}>${option}</option>`).join('')}</select>
<noscript><button type="submit">Apply filter</button></noscript>
</form>
${tasks.length ? `<ul>${tasks.map((task) => taskRow(task, project, filter, task.id === taskRenameId ? taskRenameError : '')).join('')}</ul>` : '<p class="empty">No tasks match this filter.</p>'}`);
  }

  const normalizeProjectFilter = (value) => value === 'Archived' ? 'Archived' : 'Active';

  function projectsPage(filter = 'Active', error = '') {
    const projects = listProjects.all(filter === 'Archived' ? 1 : 0);
    return page('Projects', `<h1>Workboard</h1>
<form method="post" action="/projects">
<input type="hidden" name="filter" value="${filter}">
<label for="project-name">Project name</label>
<div class="fields"><input id="project-name" name="name" type="text"${error ? ' aria-describedby="name-error" aria-invalid="true"' : ''}><button type="submit">Create project</button></div>
${error ? `<p id="name-error" role="alert">${escapeHtml(error)}</p>` : ''}
</form>
<h2>Projects</h2>
<form class="filter" method="get" action="/">
<label for="project-filter">Project filter</label>
<select id="project-filter" name="filter" onchange="this.form.requestSubmit()">${['Active', 'Archived'].map((option) => `<option${option === filter ? ' selected' : ''}>${option}</option>`).join('')}</select>
<noscript><button type="submit">Apply filter</button></noscript>
</form>
${projects.length ? `<ul>${projects.map((project) => `<li data-testid="project-row"><span class="name">${escapeHtml(project.name)}</span><span data-testid="project-summary">${project.completed}/${project.total} completed</span><div class="actions"><form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form><form method="post" action="/projects/${project.id}/${filter === 'Archived' ? 'restore' : 'archive'}"><button type="submit">${filter === 'Archived' ? 'Restore project' : 'Archive project'}</button></form></div></li>`).join('')}</ul>` : '<p class="empty">No projects yet.</p>'}`);
  }

  const server = createServer(async (request, response) => {
    try {
      const url = new URL(request.url, 'http://localhost');
      const pathname = url.pathname;
      const projectRoute = pathname.match(/^\/projects\/([1-9]\d*)(?:\/tasks(?:\/([1-9]\d*)\/(completion|rename))?|\/(archive|restore|rename))?$/);
      if (request.method === 'GET' && pathname === '/health') {
        response.writeHead(200, { 'Content-Type': 'application/json' });
        response.end(JSON.stringify({ status: 'ok' }));
      } else if (request.method === 'GET' && pathname === '/') {
        sendHtml(response, 200, projectsPage(normalizeProjectFilter(url.searchParams.get('filter'))));
      } else if (request.method === 'POST' && pathname === '/projects') {
        const form = await readForm(request);
        const name = (form.get('name') ?? '').trim();
        if (!name) {
          sendHtml(response, 422, projectsPage(normalizeProjectFilter(form.get('filter')), 'Project name is required'));
          return;
        }
        insertProject.run(name);
        response.writeHead(303, { Location: '/' });
        response.end();
      } else if (projectRoute) {
        const id = Number(projectRoute[1]);
        const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
        if (!project) {
          sendHtml(response, 404, page('Not found', '<h1>Project not found</h1><form action="/" method="get"><button>Projects</button></form>'));
          return;
        }
        const normalizeFilter = (value) => ['All', 'Open', 'Completed'].includes(value) ? value : 'All';
        if (request.method === 'GET' && pathname === `/projects/${id}`) {
          sendHtml(response, 200, projectPage(project, normalizeFilter(url.searchParams.get('filter'))));
        } else if (request.method === 'POST' && projectRoute[4] === 'rename') {
          const form = await readForm(request);
          const currentProject = findProject.get(id);
          const filter = normalizeFilter(form.get('filter'));
          if (currentProject.archived) {
            sendHtml(response, 403, projectPage(currentProject, filter, { renameError: 'Archived project is read-only' }));
            return;
          }
          const name = (form.get('name') ?? '').trim();
          if (!name) {
            sendHtml(response, 422, projectPage(currentProject, filter, { renameError: 'Project name is required' }));
            return;
          }
          renameProject.run(name, id);
          response.writeHead(303, { Location: `/projects/${id}?filter=${filter}` });
          response.end();
        } else if (request.method === 'POST' && projectRoute[4]) {
          updateArchive.run(projectRoute[4] === 'archive' ? 1 : 0, id);
          response.writeHead(303, { Location: projectRoute[4] === 'archive' ? '/' : '/?filter=Archived' });
          response.end();
        } else if (request.method === 'POST' && pathname.endsWith('/tasks')) {
          const form = await readForm(request);
          if (findProject.get(id).archived) {
            sendHtml(response, 403, projectPage(findProject.get(id), normalizeFilter(form.get('filter')), { taskError: 'Archived project is read-only' }));
            return;
          }
          const title = (form.get('title') ?? '').trim();
          const filter = normalizeFilter(form.get('filter'));
          if (!title) {
            sendHtml(response, 422, projectPage(project, filter, { taskError: 'Task title is required' }));
            return;
          }
          insertTask.run(id, title);
          response.writeHead(303, { Location: `/projects/${id}?filter=${filter}` });
          response.end();
        } else if (request.method === 'POST' && projectRoute[2]) {
          const form = await readForm(request);
          if (findProject.get(id).archived) {
            sendHtml(response, 403, projectPage(findProject.get(id), normalizeFilter(form.get('filter')), { taskError: 'Archived project is read-only' }));
            return;
          }
          const taskId = Number(projectRoute[2]);
          if (!Number.isSafeInteger(taskId) || !findTask.get(taskId, id)) {
            sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
            return;
          }
          if (projectRoute[3] === 'rename') {
            const title = (form.get('title') ?? '').trim();
            if (!title) {
              sendHtml(response, 422, projectPage(findProject.get(id), normalizeFilter(form.get('filter')), {
                taskRenameId: taskId, taskRenameError: 'Task title is required',
              }));
              return;
            }
            renameTask.run(title, taskId, id);
          } else {
            updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, id);
          }
          response.writeHead(303, { Location: `/projects/${id}?filter=${normalizeFilter(form.get('filter'))}` });
          response.end();
        } else {
          sendHtml(response, 404, page('Not found', '<h1>Page not found</h1>'));
        }
      } else {
        sendHtml(response, 404, page('Not found', '<h1>Page not found</h1>'));
      }
    } catch (error) {
      if (!error.status) console.error(error);
      if (!response.headersSent) {
        sendHtml(response, error.status ?? 500, page('Error', '<h1>Unable to complete request</h1>'));
      } else {
        response.end();
      }
    }
  });
  server.on('close', () => database.close());
  return server;
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';

async function startServer(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', (chunk) => { errors += chunk; });
  const baseUrl = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      child.kill();
      reject(new Error(`Server startup timed out: ${errors}`));
    }, 5000);
    child.once('error', (error) => { clearTimeout(timer); reject(error); });
    child.once('exit', (code) => {
      clearTimeout(timer);
      reject(new Error(`Server exited with ${code}: ${errors}`));
    });
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) {
        clearTimeout(timer);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    baseUrl,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

async function createProject(baseUrl, name) {
  return fetch(`${baseUrl}/projects`, {
    method: 'POST',
    body: new URLSearchParams({ name }),
    redirect: 'manual',
  });
}

function rows(html) {
  return [...html.matchAll(/<li data-testid="project-row">(.*?)<\/li>/gs)].map((match) => match[1]);
}

function taskRows(html) {
  return [...html.matchAll(/<li data-testid="task-row">(.*?)<\/li>/gs)].map((match) => match[1]);
}

async function postForm(baseUrl, path, values) {
  return fetch(baseUrl + path, {
    method: 'POST',
    body: new URLSearchParams(values),
    redirect: 'manual',
  });
}

test('tasks validate, filter, remain project-owned, and persist completion across restarts', { timeout: 15000 }, async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-tasks-'));
  let server;
  try {
    const databasePath = join(directory, 'workboard.sqlite');
    server = await startServer(databasePath);
    await createProject(server.baseUrl, 'First');
    await createProject(server.baseUrl, 'Second');
    const readProject = async (path = '/projects/1') => (await fetch(server.baseUrl + path)).text();
    const initial = await readProject();
    assert.match(initial, /<label for="task-title">Task title<\/label>/);
    assert.match(initial, />Create task<\/button>/);
    assert.match(initial, /<label for="task-filter">Task filter<\/label>/);
    assert.match(initial, /<option selected>All<\/option><option>Open<\/option><option>Completed<\/option>/);
    for (const title of ['', ' \t\n ']) {
      const invalid = await postForm(server.baseUrl, '/projects/1/tasks', { title });
      assert.equal(invalid.status, 422);
      const html = await invalid.text();
      assert.match(html, /role="alert">Task title is required/);
      assert.equal(taskRows(html).length, 0);
    }
    for (const title of ['  First task  ', '<b>Second</b> & "task"']) {
      assert.equal((await postForm(server.baseUrl, '/projects/1/tasks', { title })).status, 303);
    }
    const originalRows = taskRows(await readProject());
    assert.equal(originalRows.length, 2);
    assert.match(originalRows[0], /<span class="name">First task<\/span>/);
    assert.match(originalRows[0], /type="checkbox".*aria-label="Complete First task"/);
    assert.match(originalRows[1], /aria-label="Complete &lt;b&gt;Second&lt;\/b&gt; &amp; &quot;task&quot;"/);
    assert.ok(originalRows.every((row) => !row.includes(' checked')));
    assert.deepEqual(taskRows(await readProject('/projects/1?filter=Open')), originalRows.map((row) => row.replaceAll('value="All"', 'value="Open"')));
    assert.equal(taskRows(await readProject('/projects/1?filter=Completed')).length, 0);
    assert.equal(taskRows(await readProject('/projects/2')).length, 0);

    const completionPath = originalRows[0].match(/action="([^"]+\/completion)"/)[1];
    const checked = await postForm(server.baseUrl, completionPath, { completed: '1', filter: 'Open' });
    assert.equal(checked.status, 303);
    assert.equal(checked.headers.get('location'), '/projects/1?filter=Open');
    assert.equal(taskRows(await readProject('/projects/1?filter=Open')).length, 1);
    const completedRows = taskRows(await readProject('/projects/1?filter=Completed'));
    assert.equal(completedRows.length, 1);
    assert.match(completedRows[0], /aria-label="Complete First task" checked/);
    assert.equal((await postForm(server.baseUrl, completionPath.replace('/projects/1/', '/projects/2/'), { completed: '0' })).status, 404);
    assert.equal((await postForm(server.baseUrl, '/projects/999/tasks', { title: 'Missing' })).status, 404);
    assert.equal((await postForm(server.baseUrl, '/projects/1/tasks/999/completion', { completed: '1' })).status, 404);
    assert.deepEqual(taskRows(await readProject('/projects/1?filter=Completed')), completedRows);
    const invalid = await postForm(server.baseUrl, '/projects/1/tasks', { title: ' ' });
    assert.equal(taskRows(await invalid.text()).length, 2);

    const persistedRows = taskRows(await readProject());
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual(taskRows(await readProject()), persistedRows);
    assert.equal(taskRows(await readProject('/projects/2')).length, 0);
    assert.equal((await postForm(server.baseUrl, completionPath, {})).status, 303);
    assert.deepEqual(taskRows(await readProject()), originalRows);
    await postForm(server.baseUrl, '/projects/2/tasks', { title: 'Other project task' });
    assert.equal(taskRows(await readProject('/projects/2')).length, 1);
    assert.deepEqual(taskRows(await readProject()), originalRows);
    assert.equal(taskRows(await readProject('/projects/1?filter=unknown')).length, 2);
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual(taskRows(await readProject()), originalRows);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('projects validate, navigate, and persist through a server process restart', { timeout: 15000 }, async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const databasePath = join(directory, 'nested', 'projects.sqlite');
  let server;
  try {
    server = await startServer(databasePath);
    const health = await fetch(`${server.baseUrl}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });

    const initial = await (await fetch(server.baseUrl)).text();
    assert.match(initial, /<h1>Workboard<\/h1>/);
    assert.match(initial, /<label for="project-name">Project name<\/label>/);
    assert.match(initial, /<input id="project-name" name="name" type="text"/);
    assert.match(initial, />Create project<\/button>/);
    assert.equal(rows(initial).length, 0);

    for (const name of ['', '  \t\n  ']) {
      const invalid = await createProject(server.baseUrl, name);
      assert.equal(invalid.status, 422);
      const html = await invalid.text();
      assert.match(html, /role="alert">Project name is required/);
      assert.equal(rows(html).length, 0);
    }

    for (const name of ['  First project  ', '<script>alert("test")</script> & second']) {
      const created = await createProject(server.baseUrl, name);
      assert.equal(created.status, 303);
      assert.equal(created.headers.get('location'), '/');
    }
    const list = await (await fetch(server.baseUrl)).text();
    const projectRows = rows(list);
    assert.equal(projectRows.length, 2);
    assert.match(projectRows[0], /<span class="name">First project<\/span>/);
    assert.match(projectRows[1], /&lt;script&gt;alert\(&quot;test&quot;\)&lt;\/script&gt; &amp; second/);
    const projectPaths = projectRows.map((row) => {
      assert.match(row, />Open project<\/button>/);
      return row.match(/action="(\/projects\/\d+)"/)[1];
    });
